mapper.select:
SELECT  tt.*,
 (SELECT scv.MEANING
                  FROM sys_code_b sc, sys_code_value_b scv
                  WHERE sc.CODE_ID = scv.CODE_ID
                  AND sc.CODE = 'INVOICE_HANDOVER_STATUS'
                  AND scv.value =tt.handover_status
                  ) AS handover_status_n,
      (SELECT
      e.NAME
      FROM
      sys_user s,
      sys_user_allocation a,
      fnd_employee e,
      fnd_employee_assigns fa
      WHERE
      s.user_id = a.user_id
      AND a.EMPLOYEE_ASSIGN_ID = fa.EMPLOYEE_ASSIGN_ID
      AND fa.EMPLOYEE_ID = e.EMPLOYEE_ID

      and a.USER_ID=tt.handover_person)
      AS handover_person_n     FROM   invoice_handover_application     tt


          ( tt.handover_person =#{handoverPerson}   or tt.created_by =#{handoverPerson})


              and tt.document_number like #{documentNumber}


              and to_char(tt.invoice_date,'yyyy-MM-dd') >   #{invoiceDateFrom}


              and to_char(tt.invoice_date,'yyyy-MM-dd') <     #{invoiceDateTo}



              and tt.bp_name like #{bpName}


              and tt.handover_status = #{handoverStatus}



              and tt.contract_number like #{contractNumber}



              and tt.host_partment = #{hostPartment}


              and tt.billing_method = #{billingMethod}

SELECT  tt.*,
 (SELECT scv.MEANING
                  FROM sys_code_b sc, sys_code_value_b scv
                  WHERE sc.CODE_ID = scv.CODE_ID
                  AND sc.CODE = 'INVOICE_HANDOVER_STATUS'
                  AND scv.value =tt.handover_status
                  ) AS handover_status_n,
      (SELECT
      e.NAME
      FROM
      sys_user s,
      sys_user_allocation a,
      fnd_employee e,
      fnd_employee_assigns fa
      WHERE
      s.user_id = a.user_id
      AND a.EMPLOYEE_ASSIGN_ID = fa.EMPLOYEE_ASSIGN_ID
      AND fa.EMPLOYEE_ID = e.EMPLOYEE_ID

      and a.USER_ID=tt.handover_person)
      AS handover_person_n      FROM   invoice_handover_application

     tt

          tt.handover_status in ('TRANSFERING','TRANSFER_END')
          and  tt.handover_person =#{handoverPerson}


              and tt.document_number like #{documentNumber}


              and to_char(tt.invoice_date,'yyyy-MM-dd') >   #{invoiceDateFrom}


              and to_char(tt.invoice_date,'yyyy-MM-dd') <     #{invoiceDateTo}



              and tt.bp_name like #{bpName}


              and tt.handover_status = #{handoverStatus}



              and tt.contract_number like #{contractNumber}



              and tt.host_partment = #{hostPartment}


              and tt.billing_method = #{billingMethod}
